class Counter {
    // State
    int count = 0;

    // Behaviors that modify state
    void increment() {
        count = count + 1;
    }

    void reset() {
        count = 0;
    }

    void printCurrentCount() {
        System.out.println("Current count: " + count);
    }
}

public class Main {
    public static void main(String[] args) {
        Counter c = new Counter();
        c.printCurrentCount(); // Current count: 0

        c.increment();
        c.increment();
        c.increment();
        c.printCurrentCount(); // Current count: 3

        c.reset();
        c.printCurrentCount(); // Current count: 0
    }
}

