class Student {
    String name;
    int age;

    void haveBirthday() {
        age = age + 1;
        System.out.println(name + " is now " + age + " years old!");
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student();
        s.name = "Rahul";
        s.age = 20;
        s.haveBirthday();
    }
}

class LightBulb {
    boolean isOn = false;

    void turnOn() {
        isOn = true;
        System.out.println("Bulb is ON");
    }

    void turnOff() {
        isOn = false;
        System.out.println("Bulb is OFF");
    }
}

public class Main {
    public static void main(String[] args) {
        LightBulb bulb = new LightBulb();
        bulb.turnOn();
        bulb.turnOff();
    }
}
